using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.ENC.TiposPregunta;namespace GraphApi.Services.ENC.TiposPregunta{    public class TiposPreguntaService : ITiposPreguntaService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public TiposPreguntaService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadTiposPregunta>> GetTiposPreguntas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM enc.TiposPregunta (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadTiposPregunta>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetTiposPreguntasDynamic(            int? tipoPreguntaID,            string? tipoPregunta,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "TipoPreguntaID, TipoPregunta, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM enc.TiposPregunta (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (tipoPreguntaID.HasValue)            {                vSql.Append(" AND TipoPreguntaID = @TipoPreguntaID");                vParameters.Add("TipoPreguntaID",tipoPreguntaID);            }            if (!string.IsNullOrWhiteSpace(tipoPregunta))            {                vSql.Append(" AND TipoPregunta LIKE @TipoPregunta");                vParameters.Add("TipoPregunta",$"%{tipoPregunta}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadTiposPregunta> CreateTiposPregunta(clCreateTiposPregunta objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO enc.TiposPregunta                (TipoPregunta, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@TipoPregunta, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.TipoPregunta,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT TipoPreguntaID, TipoPregunta, bEliminado                FROM enc.TiposPregunta (NOLOCK)                WHERE TipoPreguntaID = @TipoPreguntaID;";            var vReadParams = new { TipoPreguntaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadTiposPregunta>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el TiposPregunta con ID {vNewId}.");            return vCreated;        }        public async Task<clReadTiposPregunta?> UpdateTiposPregunta(clUpdateTiposPregunta objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("TipoPreguntaID", objInput.TipoPreguntaID);            if (objInput.TipoPregunta is not null)            {                vSets.Add("TipoPregunta = @TipoPregunta");                vParameters.Add("TipoPregunta", objInput.TipoPregunta);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE enc.TiposPregunta                SET {vSetClause}                WHERE TipoPreguntaID = @TipoPreguntaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT TipoPreguntaID, TipoPregunta, bEliminado                FROM enc.TiposPregunta (NOLOCK)                WHERE TipoPreguntaID = @TipoPreguntaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadTiposPregunta>(sSelect, new {  objInput.TipoPreguntaID });        }        public async Task<bool> DeleteTiposPregunta(int nTiposPreguntaID)        {            const string sSql = @"                DELETE FROM enc.TiposPregunta                WHERE TipoPreguntaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nTiposPreguntaID });            return vAffected > 0;        }    }}